#include "exercise.h"
#include <ctype.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static bool used[676000];
static unsigned next_name = 0;
bool robot_create(robot *r) {
    for (unsigned i = 0; i < 676000; i++) {
        unsigned n = (unsigned)(((uint64_t)next_name++ * 104729 + 7919) % 676000);
        if (used[n])
            continue;
        used[n] = true;
        r->name[0] = (char)('A' + n / 26000);
        r->name[1] = (char)('A' + n / 1000 % 26);
        snprintf(r->name + 2, 4, "%03u", n % 1000);
        return true;
    }
    return false;
}
bool robot_reset(robot *r) { return robot_create(r); }
